import{_ as s,l as n,o as a,c as o,v as t,p as l,x as i,d as c,i as u,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Quine–McCluskey","description":"","frontmatter":{"title":"Quine–McCluskey","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quine-mccluskey.md","filePath":"cs/quine-mccluskey.md","lastUpdated":1789023840000}'),h={name:"cs/quine-mccluskey.md"};function p(E,e,m,_,k,f){const r=n("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t('<h1 id="quine–mccluskey" tabindex="-1">Quine–McCluskey <a class="header-anchor" href="#quine–mccluskey" aria-label="Permalink to &quot;Quine–McCluskey&quot;">​</a></h1><div class="epigraph"><p>把最小项按 $1$ 的个数分层，只合并差一位的对，列表就能代替格子；剩下的是集合覆盖，不是再画更大的图。</p><footer>—— 据 Quine, The Problem of Simplifying Truth Functions, 1952；McCluskey, Minimization of Boolean Functions, 1956 整理</footer></div><p>上一课<a href="/cs/karnaugh-map">卡诺图与化简</a>钉死了：格雷码网格上 \\(2^k\\) 相邻圈对应消去 \\(k\\) 个变量。本课不重画四变量图，也不从「逻辑综合史」另起。缺口是：\\(n\\ge 5\\) 时图要对折，眼力覆盖不是算法。完全指定函数仍要两级 SOP，需要一份<strong>可程序化的列表</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>卡诺图把汉明距离 \\(1\\) 画成邻居。同一合并，写成：将最小项当二进制编号，只把差一位且未用过的对合成带 <code>-</code> 的蕴涵项，再重复，直到不能合并。活下来的是<strong>质蕴涵项</strong>。缺口的另一半：每个 \\(1\\) 必须被盖住；本质质蕴涵项先拿走，其余是集合覆盖（Petrick 或枚举）。这不是多项式时间保证最优——本课承认 NP 难，手算只处理小表。</p><p>无关项与险象故意留给<a href="/cs/dont-care-hazard">下一课</a>。本课函数完全指定。</p><h3 id="质蕴涵项不是「最长的圈」" tabindex="-1">质蕴涵项不是「最长的圈」 <a class="header-anchor" href="#质蕴涵项不是「最长的圈」" aria-label="Permalink to &quot;质蕴涵项不是「最长的圈」&quot;">​</a></h3><p>质蕴涵项是不能再扩大的乘积项。最短 SOP 还可能丢掉某些非本质项。把「列出全部质蕴涵项」当成已经最小，覆盖表会少做一列。</p><p><span class="marginnote">Quine 给出质蕴涵项的逻辑定义。McCluskey 把表格法写成工程步骤，与卡诺图同一代数：合并差一位的最小项。后课综合器走的是同类覆盖，规模用启发式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>(1) 列出 \\(f=1\\) 的最小项。(2) 按重量分组，合并差一位者，标记被合并项。(3) 未被标记的项即质蕴涵项。(4) 覆盖表：行是质蕴涵项，列是最小项；先取只被一行盖住的本质项，再覆盖剩余列。</p>',11)),(a(),l(d,null,{default:i(()=>[u(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MINTERM%5B%22%E6%9C%80%E5%B0%8F%E9%A1%B9%E5%88%97%E8%A1%A8%22%5D%20--%3E%20MERGE%5B%22%E5%B7%AE%E4%B8%80%E4%BD%8D%E5%90%88%E5%B9%B6%22%5D%0A%20%20MERGE%20--%3E%20PI%5B%22%E8%B4%A8%E8%95%B4%E6%B6%B5%E9%A1%B9%22%5D%0A%20%20PI%20--%3E%20COVER%5B%22%E8%A6%86%E7%9B%96%E8%A1%A8%22%5D%0A%20%20COVER%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AX%20%E4%B8%8E%E9%99%A9%E8%B1%A1%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>列表法与卡诺图输出同一类两级式，只是邻接改由编号异或重量为 \\(1\\) 判定——<a href="/cs/gray-code">Gray 码</a>课的相邻在这里变成整数差一位。面积与延迟仍是两级与或；多级分解不在本课。后课 ALU 控制若变量多，默认不再手画六维图，而承认用表或工具做覆盖。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理 \\(X\\)、不消静态险象、不把 Espresso 等启发式写成步骤。多输出共享乘积项是另一张覆盖表。时序激励函数会用同一算法，状态对象还没有。</p><p>后课默认：完全指定函数的两级最小 SOP 可用 Quine–McCluskey 列出质蕴涵项再覆盖；不完全指定与毛刺另说。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>按重量合并差一位的项，得到质蕴涵项。</li><li>最短式还要做集合覆盖；本质项先取。</li><li>与卡诺图同代数，可程序化，不保证大 \\(n\\) 可手算。</li><li>出处：Quine, 1952；McCluskey, 1956。</li></ul>',7))])}const P=s(h,[["render",p]]);export{B as __pageData,P as default};
